package com.example.labradorpuppy.client;

import org.joml.Matrix4f;

import java.io.IOException;
import java.io.InputStream;
import java.nio.ByteBuffer;
import java.nio.ByteOrder;

/**
 * Static puppy mesh + skinning data, loaded once from
 * assets/labrador_puppy/mesh/puppy_mesh.bin (generated by tools/build_assets.py).
 *
 * Coordinates are already in Minecraft "model space": 1 unit = 1 block, +Y is DOWN,
 * the front of the dog points to -Z and the feet are at y = 1.501 (this is exactly what
 * LivingEntityRenderer expects, same as every vanilla model).
 */
public final class PuppyMesh {
    private static final String PATH = "/assets/labrador_puppy/mesh/puppy_mesh.bin";
    private static PuppyMesh instance;

    public final int boneCount;
    public final int[] boneParent;
    public final float[] pivot;      // boneCount * 3

    public final int vertexCount;
    public final float[] pos;        // vertexCount * 3
    public final float[] nrm;        // vertexCount * 3
    public final float[] uv;         // vertexCount * 2
    public final byte[] boneIdx;     // vertexCount * 4
    public final float[] boneW;      // vertexCount * 4

    public final int triCount;
    public final int[] tris;         // triCount * 3

    public static synchronized PuppyMesh get() {
        if (instance == null) {
            instance = load();
        }
        return instance;
    }

    private static PuppyMesh load() {
        try (InputStream in = PuppyMesh.class.getResourceAsStream(PATH)) {
            if (in == null) {
                throw new IllegalStateException("Missing resource " + PATH);
            }
            ByteBuffer bb = ByteBuffer.wrap(in.readAllBytes()).order(ByteOrder.LITTLE_ENDIAN);
            return new PuppyMesh(bb);
        } catch (IOException e) {
            throw new IllegalStateException("Could not read " + PATH, e);
        }
    }

    private PuppyMesh(ByteBuffer bb) {
        if (bb.getInt() != 0x4D505550 || bb.getInt() != 1) {
            throw new IllegalStateException("Bad puppy mesh file (magic/version)");
        }
        boneCount = bb.getInt();
        boneParent = new int[boneCount];
        pivot = new float[boneCount * 3];
        for (int i = 0; i < boneCount; i++) {
            boneParent[i] = bb.getInt();
            pivot[i * 3] = bb.getFloat();
            pivot[i * 3 + 1] = bb.getFloat();
            pivot[i * 3 + 2] = bb.getFloat();
        }
        vertexCount = bb.getInt();
        triCount = bb.getInt();
        pos = new float[vertexCount * 3];
        nrm = new float[vertexCount * 3];
        uv = new float[vertexCount * 2];
        boneIdx = new byte[vertexCount * 4];
        boneW = new float[vertexCount * 4];
        for (int i = 0; i < vertexCount; i++) {
            pos[i * 3] = bb.getFloat();
            pos[i * 3 + 1] = bb.getFloat();
            pos[i * 3 + 2] = bb.getFloat();
            nrm[i * 3] = bb.getFloat();
            nrm[i * 3 + 1] = bb.getFloat();
            nrm[i * 3 + 2] = bb.getFloat();
            uv[i * 2] = bb.getFloat();
            uv[i * 2 + 1] = bb.getFloat();
            bb.get(boneIdx, i * 4, 4);
            for (int k = 0; k < 4; k++) {
                boneW[i * 4 + k] = bb.getFloat();
            }
        }
        tris = new int[triCount * 3];
        for (int i = 0; i < tris.length; i++) {
            tris[i] = bb.getInt();
        }
    }

    /**
     * Linear-blend skinning on the CPU.
     *
     * @param world   world matrix of every bone (see {@link PuppyPose#computeWorld})
     * @param scratch float[boneCount * 16] scratch buffer
     * @param outPos  float[vertexCount * 3]
     * @param outNrm  float[vertexCount * 3]
     */
    public void skin(Matrix4f[] world, float[] scratch, float[] outPos, float[] outNrm) {
        for (int b = 0; b < boneCount; b++) {
            world[b].get(scratch, b * 16);   // column-major
        }
        for (int v = 0; v < vertexCount; v++) {
            float x = pos[v * 3], y = pos[v * 3 + 1], z = pos[v * 3 + 2];
            float nx = nrm[v * 3], ny = nrm[v * 3 + 1], nz = nrm[v * 3 + 2];
            float ox = 0, oy = 0, oz = 0, onx = 0, ony = 0, onz = 0;
            for (int k = 0; k < 4; k++) {
                float w = boneW[v * 4 + k];
                if (w <= 0f) continue;
                int m = (boneIdx[v * 4 + k] & 0xFF) * 16;
                ox += w * (scratch[m] * x + scratch[m + 4] * y + scratch[m + 8] * z + scratch[m + 12]);
                oy += w * (scratch[m + 1] * x + scratch[m + 5] * y + scratch[m + 9] * z + scratch[m + 13]);
                oz += w * (scratch[m + 2] * x + scratch[m + 6] * y + scratch[m + 10] * z + scratch[m + 14]);
                onx += w * (scratch[m] * nx + scratch[m + 4] * ny + scratch[m + 8] * nz);
                ony += w * (scratch[m + 1] * nx + scratch[m + 5] * ny + scratch[m + 9] * nz);
                onz += w * (scratch[m + 2] * nx + scratch[m + 6] * ny + scratch[m + 10] * nz);
            }
            float len = (float) Math.sqrt(onx * onx + ony * ony + onz * onz);
            if (len > 1.0e-6f) {
                onx /= len; ony /= len; onz /= len;
            }
            outPos[v * 3] = ox; outPos[v * 3 + 1] = oy; outPos[v * 3 + 2] = oz;
            outNrm[v * 3] = onx; outNrm[v * 3 + 1] = ony; outNrm[v * 3 + 2] = onz;
        }
    }
}
